// 2Ship RR_WOODFALL (SCENE_21MITURINMAE)
static void Init_RR_MM_WOODFALL() {
    areaTable[RR_MM_WOODFALL] = Region("MM Woodfall", SCENE_ID_MAX, TIME_DOESNT_PASS, {RA_NONE}, {
    }, {
        //Locations
        LOCATION(RC_MM_WOODFALL_ENTRANCE_CHEST, mm->CanBeDeku() || (logic->Get(LOGIC_MM_CLEARED_WOODFALL_TEMPLE) && (mm->CanBeZora() || mm->CanBeGoron() || mm->CanSwim()))),
        LOCATION(RC_MM_WOODFALL_PIECE_OF_HEART_CHEST, mm->CanBeDeku() && (mm->CanKillEnemy(MMA_EN_DEKUNUTS) || mm->Has(MMI_HOOKSHOT))),
        LOCATION(RC_MM_WOODFALL_FREESTANDING_RUPEE, mm->CanBeDeku() && mm->CanKillEnemy(MMA_EN_DEKUNUTS)),
        LOCATION(RC_MM_WOODFALL_GRASS_01, true),
        LOCATION(RC_MM_WOODFALL_GRASS_02, true),
        LOCATION(RC_MM_WOODFALL_GRASS_03, true),
        LOCATION(RC_MM_WOODFALL_GRASS_04, true),
        LOCATION(RC_MM_WOODFALL_GRASS_05, true),
        LOCATION(RC_MM_WOODFALL_GRASS_06, true),
        LOCATION(RC_MM_ENEMY_DROP_DRAGONFLY, mm->CanKillEnemy(MMA_EN_GRASSHOPPER)),
        LOCATION(RC_MM_ENEMY_DROP_HIPLOOP, mm->CanKillEnemy(MMA_EN_PP)),
        LOCATION(RC_MM_ENEMY_DROP_MAD_SCRUB, mm->CanKillEnemy(MMA_EN_DEKUNUTS)),
    }, {
        //Exits
        ENTRANCE(RR_MM_SOUTHERN_SWAMP_SOUTH_UPPER, true),
        ENTRANCE(RR_MM_WOODFALL_GREAT_FAIRY_FOUNTAIN, mm->CanBeDeku() && mm->CanKillEnemy(MMA_EN_DEKUNUTS)),
        ENTRANCE(RR_MM_WOODFALL_TEMPLE_DEKU_PRINCESS_ROOM, logic->Get(LOGIC_MM_CLEARED_WOODFALL_TEMPLE)),
        ENTRANCE(RR_MM_WOODFALL_OWL_STATUE_PLATFORM, mm->CanBeDeku() && mm->CanKillEnemy(MMA_EN_DEKUNUTS)),
    });
    areaTable[RR_MM_WOODFALL].world = RW_TERMINA;
}

